import { lazy, Suspense, type ReactNode } from "react";

export type ThemeName = "kodosi";

export const themeNames: ThemeName[] = ["kodosi"];

export type KcEnvName = "KODOSI_TERMS_URL" | "KODOSI_PRIVACY_URL";

export const kcEnvNames: KcEnvName[] = ["KODOSI_TERMS_URL", "KODOSI_PRIVACY_URL"];

export const kcEnvDefaults: Record<KcEnvName, string> = {
  "KODOSI_TERMS_URL": "",
  "KODOSI_PRIVACY_URL": ""
};

/**
 * NOTE: Do not import this type except maybe in your entrypoint. 
 * If you need to import the KcContext import it either from src/login/KcContext.ts or src/account/KcContext.ts.
 * Depending on the theme type you are working on.
 */
export type KcContext =
    | import("./login/KcContext").KcContext
    | import("./account/KcContext").KcContext
    ;

declare global {
    interface Window {
        kcContext?: KcContext;
    }
}

export const KcLoginPage = lazy(() => import("./login/KcPage"));
export const KcAccountPage = lazy(() => import("./account/KcPage"));

export function KcPage(
    props: {
        kcContext: KcContext;
        fallback?: ReactNode;
    }
) {
    const { kcContext, fallback } = props;
    return (
        <Suspense fallback={fallback}>
            {(() => {
                switch (kcContext.themeType) {
                    case "login": return <KcLoginPage kcContext={kcContext} />;
                    case "account": return <KcAccountPage kcContext={kcContext} />;
                }
            })()}
        </Suspense>
    );
}

